const BIN_ASSETS = {"/apple-touch-icon.png": {"b64": "", "type": "image/png"}, "/favicon.png": {"b64": "", "type": "image/png"}, "/icon-192.png": {"b64": "", "type": "image/png"}, "/icon-512.png": {"b64": "", "type": "image/png"}};

function b64ToBytes(b64) {
  const binStr = atob(b64);
  const len = binStr.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binStr.charCodeAt(i);
  return bytes;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let path = url.pathname;
    if (path === "/snapshot.js") {
      return new Response("Not Found", { status: 404, headers: { "Content-Type": "text/plain" } });
    }
    if (TEXT_ASSETS[path]) {
      return new Response(TEXT_ASSETS[path].body, {
        status: 200,
        headers: {
          "Content-Type": TEXT_ASSETS[path].type,
          "Cache-Control": "no-store, max-age=0"
        }
      });
    }
    if (BIN_ASSETS[path]) {
      return new Response(b64ToBytes(BIN_ASSETS[path].b64), {
        status: 200,
        headers: {
          "Content-Type": BIN_ASSETS[path].type,
          "Cache-Control": "public, max-age=3600"
        }
      });
    }
    return new Response(TEXT_ASSETS["/"].body, {
      status: 200,
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "no-store, max-age=0"
      }
    });
  }
};